# Figure 2C Gene Ontology enrichment
# Use the complete stage-associated gene sets produced by fig2_embry_heatmap.ipynb.

#1. =========== Shared configuration
# Replace each ROOT placeholder with the required file or directory path before running.
ROOT <- "."  # Set the working path.
# Uses Stage-DEG.tsv.gz generated by fig2_embry_heatmap.ipynb.
INPUT_FILE <- ROOT
# Set the file or directory path.
OUT_DIR <- ROOT
# Set the file or directory path.
RESULT_FILE <- ROOT
STAGES <- c("E9.5", "E10.5", "E11.5", "E13.5", "E14.5", "E15.5", "E16.5", "E17.5", "E18.5")
REBUILD_RESULTS <- FALSE             # Set TRUE to rebuild after changing the inputs or analysis settings.
ANALYZE_ONLY <- "--analyze-only" %in% commandArgs(trailingOnly = TRUE)
dir.create(OUT_DIR, recursive = TRUE, showWarnings = FALSE)
Sys.setenv(OMP_NUM_THREADS = "1", OPENBLAS_NUM_THREADS = "1", MKL_NUM_THREADS = "1")

suppressPackageStartupMessages({
  library(AnnotationDbi)
  library(org.Mm.eg.db)
  library(GO.db)
  library(ggplot2)
})

#2. =========== Complete stage gene sets and matched BP annotation
MIN_GO_SIZE <- 10                    # Unique background genes annotated to a term.
MAX_GO_SIZE <- 500
FDR_THRESHOLD <- 0.05               # BH across all stage x original-comparison x BP tests.
MIN_SUPPORT_GENES <- 3              # Display support only; does not filter the tested family.
N_TERMS <- 15                       # Unique GO rows; retain all original GO terms.

build_results <- function() {
  deg <- read.delim(gzfile(INPUT_FILE), stringsAsFactors = FALSE, check.names = FALSE)
  for (field in c("tested", "qualified")) deg[[field]] <- tolower(as.character(deg[[field]])) == "true"
  # Use the exploratory comparison available across all nine stages.
  # Keep the separate three-stage formal contrasts out of this test family.
  deg <- deg[deg$evidence_class == "exploratory", ]
  stopifnot(setequal(unique(deg$stage), STAGES), !anyDuplicated(deg[c("stage", "compartment", "gene_id")]))
  gene_names <- unique(deg[c("gene_id", "gene_symbol", "mgi_id")])
  tested_ids <- unique(deg$gene_id[deg$tested])
  db_keys <- keys(org.Mm.eg.db, keytype = "ENSEMBL")
  valid_keys <- intersect(tested_ids, db_keys)
  mapping <- suppressMessages(select(org.Mm.eg.db, keys = valid_keys, keytype = "ENSEMBL",
    columns = c("GOALL", "ONTOLOGYALL", "EVIDENCEALL")))
  mapping <- mapping[!is.na(mapping$GOALL) & mapping$ONTOLOGYALL == "BP" &
    mapping$GOALL != "GO:0008150" & !is.na(mapping$EVIDENCEALL) & mapping$EVIDENCEALL != "ND", ]
  mapping <- unique(mapping[c("ENSEMBL", "GOALL")])
  term_names <- suppressMessages(select(GO.db, keys = unique(mapping$GOALL), keytype = "GOID", columns = "TERM"))
  term_names <- term_names[!is.na(term_names$TERM), ]
  mapping <- mapping[mapping$GOALL %in% term_names$GOID, ]
  term_genes <- lapply(split(mapping$ENSEMBL, mapping$GOALL), unique)
  annotated_ids <- unique(mapping$ENSEMBL)
  sets <- summaries <- rows <- list()
  at <- 0L
  for (stage in STAGES) {
    for (scope in c("CVG", "SGN")) {
      d <- deg[deg$stage == stage & deg$compartment == scope, ]
      if (!nrow(d)) next
      group_id <- paste(stage, scope, sep = "|")
      background_raw <- unique(d$gene_id[d$tested])
      input_raw <- unique(d$gene_id[d$qualified])
      stopifnot(all(input_raw %in% background_raw))
      background <- intersect(background_raw, annotated_ids)
      input <- intersect(input_raw, background)
      bg_terms <- lapply(term_genes, intersect, y = background)
      K <- lengths(bg_terms)
      keep <- K >= MIN_GO_SIZE & K <= MAX_GO_SIZE
      bg_terms <- bg_terms[keep]
      K <- K[keep]
      hits <- lapply(bg_terms, intersect, y = input)
      k <- lengths(hits)
      N <- length(background)
      n <- length(input)
      stopifnot(n > 0L, n <= N, all(k <= K), all(k <= n))
      # Include every eligible term in BH correction, including zero-overlap tests.
      p <- phyper(k - 1L, K, N - K, n, lower.tail = FALSE)
      at <- at + 1L
      rows[[at]] <- data.frame(stage = stage, compartment = scope, group_id = group_id,
        GO_ID = names(K), Description = term_names$TERM[match(names(K), term_names$GOID)],
        Count = k, input_n = n, term_background_n = K, background_n = N,
        GeneRatio = k / n, BgRatio = K / N, FoldEnrichment = (k / n) / (K / N),
        PValue = p, gene_ids = vapply(hits, paste, character(1), collapse = ";"), stringsAsFactors = FALSE)
      sets[[group_id]] <- list(input_raw = input_raw, background_raw = background_raw,
        input = input, background = background)
      summaries[[at]] <- data.frame(stage = stage, compartment = scope,
        raw_input = length(input_raw), effective_input = n,
        input_unmapped = sum(!input_raw %in% db_keys), input_without_BP = sum(input_raw %in% db_keys & !input_raw %in% annotated_ids),
        raw_background = length(background_raw), effective_background = N,
        background_unmapped = sum(!background_raw %in% db_keys),
        background_without_BP = sum(background_raw %in% db_keys & !background_raw %in% annotated_ids),
        tested_terms = length(K))
      cat(stage, scope, "input", length(input_raw), "->", n, "| background", length(background_raw), "->", N, "| terms", length(K), "\n")
    }
  }
  results <- do.call(rbind, rows)
  results$FDR <- p.adjust(results$PValue, method = "BH")
  results$significant <- results$FDR < FDR_THRESHOLD
  result <- list(results = results, sets = sets, input_audit = do.call(rbind, summaries),
    gene_names = gene_names, annotation = mapping, term_names = term_names,
    parameters = list(ontology = "BP", key_type = "ENSEMBL", min_go_size = MIN_GO_SIZE,
      max_go_size = MAX_GO_SIZE, fdr_threshold = FDR_THRESHOLD, min_support_genes = MIN_SUPPORT_GENES,
      display_terms = N_TERMS, stage_order = STAGES,
      adjustment_family = "All 11 original-comparison x stage groups, all eligible BP terms, jointly BH",
      annotation_policy = "GOALL BP ancestors; all available evidence except ND; exclude BP root and invalid GO IDs"),
    provenance = list(input_file = sub(paste0(ROOT, "/"), "", INPUT_FILE, fixed = TRUE),
      input_sha256 = digest::digest(file = INPUT_FILE, algo = "sha256"),
      input_selection = "Complete qualified gene lists from the single existing nine-stage comparison branch; no display-row or peak-stage filter",
      annotation_metadata = metadata(org.Mm.eg.db),
      versions = vapply(c("AnnotationDbi", "org.Mm.eg.db", "GO.db", "ggplot2", "ragg"), function(x) as.character(packageVersion(x)), character(1)),
      R_version = R.version.string))
  result
}

#3. =========== Ranked display terms and the essential result cache
select_terms <- function(result) {
  selected <- audits <- list()
  for (stage in STAGES) {
    d <- result$results[result$results$stage == stage &
      result$results$Count >= MIN_SUPPORT_GENES & result$results$FoldEnrichment > 1, ]
    d <- d[order(d$FDR, -d$FoldEnrichment, -d$Count, d$GO_ID, d$compartment), ]
    candidates <- d[!duplicated(d$GO_ID), ]
    chosen <- head(candidates$GO_ID, N_TERMS)
    stopifnot(length(chosen) >= N_TERMS)
    selected[[stage]] <- chosen
    audits[[stage]] <- data.frame(stage = stage,
      significant_comparison_terms = sum(d$significant),
      unique_significant_terms = sum(candidates$significant),
      displayed_terms = length(chosen),
      displayed_significant_terms = sum(head(candidates$significant, N_TERMS)),
      displayed_nonsignificant_terms = sum(!head(candidates$significant, N_TERMS)))
  }
  result$display_terms <- selected
  result$display_audit <- do.call(rbind, audits)
  result$parameters$display_terms <- N_TERMS
  result$parameters$min_support_genes <- MIN_SUPPORT_GENES
  result$parameters$display_policy <- "No GO de-redundancy. Rank complete GO results by joint FDR; show at least 15 unique terms. Unfilled grey outlines identify FDR>=0.05."
  result
}

if (REBUILD_RESULTS || !file.exists(RESULT_FILE)) {
  result <- build_results()
} else {
  result <- readRDS(RESULT_FILE)
}
stopifnot(result$parameters$min_go_size == MIN_GO_SIZE, result$parameters$max_go_size == MAX_GO_SIZE,
  result$parameters$fdr_threshold == FDR_THRESHOLD)
result <- select_terms(result)
saveRDS(result, RESULT_FILE, compress = "xz")
print(result$display_audit, row.names = FALSE)
cat("Jointly tested BP hypotheses:", nrow(result$results), "| significant:", sum(result$results$significant), "\n")
if (ANALYZE_ONLY) quit(save = "no", status = 0L)

#4. =========== One stage per figure
FIG_WIDTH <- 9.0                    # Inches; leave enough width for semantic GO labels.
FONT_SIZE <- 11
LABEL_WIDTH <- 47                   # Character wrap; each GO phrase remains a single label.
PNG_DPI <- 600
BAR_HEIGHT <- 0.62                  # Row-height fraction for a single original comparison.
PAIRED_BAR_HEIGHT <- 0.28           # Fixed upper CVG / lower SGN bars within one GO row.
BAR_LABEL_SIZE <- 3.0               # Millimeters; about 8.5 pt, Arial overlap-count labels.
PALETTE <- c("#8EA4CE", "#C5CEE2", "#F5F0E3", "#F4DE9D", "#EDA264", "#C84A44")

plot_data <- do.call(rbind, lapply(STAGES, function(stage) {
  d <- result$results[result$results$stage == stage &
    result$results$GO_ID %in% result$display_terms[[stage]] &
    result$results$Count >= MIN_SUPPORT_GENES & result$results$FoldEnrichment > 1, ]
  d$term_index <- match(d$GO_ID, result$display_terms[[stage]])
  d
}))
plot_data$neg_log10_FDR <- -log10(pmax(plot_data$FDR, .Machine$double.xmin))
COLOR_MAX <- ceiling(max(plot_data$neg_log10_FDR))
RATIO_MAX <- max(plot_data$GeneRatio) * 1.22
for (stage in STAGES) {
  d <- plot_data[plot_data$stage == stage, ]
  ids <- result$display_terms[[stage]]
  if (!length(ids)) stop(paste("No display-qualified GO terms:", stage))
  terms <- result$term_names$TERM[match(ids, result$term_names$GOID)]
  labels <- vapply(terms, function(x) paste(strwrap(x, width = LABEL_WIDTH), collapse = "\n"), character(1))
  n_terms <- length(ids)
  n_lines <- lengths(strsplit(labels, "\n", fixed = TRUE))
  height <- max(7.8, 2.1 + sum(pmax(n_lines, 1L)) * 0.24)
  scopes <- unique(d$compartment)
  d$y <- n_terms + 1 - d$term_index
  paired <- length(scopes) > 1L
  if (paired) d$y <- d$y + ifelse(d$compartment == "CVG", 0.18, -0.18)
  bar_height <- if (paired) PAIRED_BAR_HEIGHT else BAR_HEIGHT
  d$end_label <- if (paired) paste0(d$compartment, ": ", d$Count) else as.character(d$Count)
  counts <- result$input_audit[result$input_audit$stage == stage, ]
  subtitle <- paste(paste0(counts$compartment, ": ", counts$effective_input, " BP-annotated input genes"), collapse = "  |  ")
  n_sig <- result$display_audit$displayed_significant_terms[result$display_audit$stage == stage]
  p <- ggplot(d, aes(xmin = 0, xmax = GeneRatio, ymin = y - bar_height / 2,
    ymax = y + bar_height / 2, fill = neg_log10_FDR)) +
    geom_rect(data = d[d$significant, ], color = "#707070", linewidth = 0.22) +
    geom_rect(data = d[!d$significant, ], fill = "white", color = "#999999", linewidth = 0.45) +
    geom_text(aes(x = GeneRatio + RATIO_MAX * 0.012, y = y, label = end_label),
      inherit.aes = FALSE, hjust = 0, size = BAR_LABEL_SIZE, family = "Arial", color = "#444444") +
    scale_fill_gradientn(colours = PALETTE, limits = c(0, COLOR_MAX), name = "-log10(joint FDR)") +
    scale_x_continuous(limits = c(0, RATIO_MAX), labels = scales::label_percent(accuracy = 1), expand = expansion(mult = c(0, 0.02))) +
    scale_y_continuous(breaks = seq_len(n_terms), labels = rev(labels), limits = c(0.45, n_terms + 0.55), expand = c(0, 0)) +
    labs(title = paste0(stage, "  |  GO biological processes"), subtitle = subtitle,
      x = "Gene ratio (overlap / BP-annotated input genes)", y = NULL,
      caption = paste0(n_terms, " terms; ", n_sig, " significant. Filled: FDR < 0.05; outlined: FDR >= 0.05.\n",
        "End labels: overlap genes. No redundancy filtering; matched backgrounds.")) +
    theme_classic(base_size = FONT_SIZE, base_family = "Arial") +
    theme(axis.text.y = element_text(color = "#202020", size = FONT_SIZE, lineheight = 0.98),
      axis.text.x = element_text(color = "#303030"), axis.ticks.y = element_blank(),
      axis.line.y = element_blank(), axis.line.x = element_line(linewidth = 0.4),
      plot.title = element_text(size = 15, face = "bold"), plot.subtitle = element_text(size = 10, color = "#505050"),
      plot.caption = element_text(size = 8.5, color = "#505050", hjust = 0),
      legend.title = element_text(size = 9), legend.text = element_text(size = 9),
      legend.key.height = grid::unit(0.55, "cm"), plot.margin = margin(12, 12, 12, 10)) +
    guides(fill = guide_colorbar(barheight = grid::unit(3, "cm"), barwidth = grid::unit(0.35, "cm")))
  # Set the file or directory path.
  filename <- ROOT
  ragg::agg_png(filename, width = FIG_WIDTH, height = height, units = "in", res = PNG_DPI, background = "white")
  print(p)
  dev.off()
  cat("Saved", basename(filename), "|", n_terms, "unique terms |", FIG_WIDTH, "x", height, "in at", PNG_DPI, "DPI\n")
}
